import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 300005;
    static long[][] dp_state = new long[27][MAX_SIZE];
    static int[] fact = new int[MAX_SIZE];
    static int[] inv_fact = new int[MAX_SIZE];

    static long power_mod(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static int get_permutation(int n, int m, int mod) {
        return (int)((long)fact[n] * inv_fact[n - m] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int MOD = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(power_mod(K, n, MOD));
            sc.close();
            return;
        }

        fact[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fact[i] = (int)((long)fact[i - 1] * i % MOD);
        }

        inv_fact[n] = (int)power_mod(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; --i) {
            inv_fact[i] = (int)((long)inv_fact[i + 1] * (i + 1) % MOD);
        }

        dp_state[0][0] = 1L;
        for (int k = 0; k < K; ++k) {
            for (int i = 1; i <= n; ++i) {
                if ((i & n) != i) continue;
                int block_mask = 1 << (31 - Integer.numberOfLeadingZeros(i));
                long res = 0L;
                int cnt = 0;
                for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                    int j_plus = j + block_mask;
                    res += dp_state[k][i ^ j_plus] * inv_fact[j_plus];
                    if (++cnt == 17) {
                        res %= MOD;
                        cnt = 0;
                    }
                    if (j == 0) break;
                }
                res %= MOD;
                dp_state[k + 1][i] = res;
            }
        }

        int total_result = 0;
        for (int i = 0; i <= K; ++i) {
            total_result = (int)((total_result + (long)fact[n] * dp_state[i][n] % MOD * get_permutation(K, i, MOD)) % MOD);
        }

        int answer = (int)((power_mod(K, n, MOD) + MOD - total_result) % MOD);
        System.out.println(answer);
        sc.close();
    }
}
